import{_ as a,C as e,c as o,o as i,j as t,b as s,a0 as r,a as n,w as l,G as d,a1 as c}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Nutrição para um Desempenho Preciso","description":"","frontmatter":{},"headers":[],"relativePath":"pt/education/nutrition/index.md","filePath":"pt/education/nutrition/index.md"}');const m=a({name:"pt/education/nutrition/index.md"},[["render",function(a,u,m,p,h,g){const b=e("Mermaid");return i(),o("div",null,[u[2]||(u[2]=t("h1",{id:"nutricao-para-um-desempenho-preciso",tabindex:"-1"},[n("Nutrição para um Desempenho Preciso "),t("a",{class:"header-anchor",href:"#nutricao-para-um-desempenho-preciso","aria-label":'Permalink to "Nutrição para um Desempenho Preciso"'},"​")],-1)),u[3]||(u[3]=t("p",null,[n("A petanca é um esporte de precisão, não de resistência. Suas necessidades nutricionais são diferentes das de um maratonista ou de um jogador de futebol. O mais importante é a "),t("strong",null,"estabilidade do combustível cerebral"),n(" — manter a mente afiada e as mãos firmes durante um longo dia de competição.")],-1)),u[4]||(u[4]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"A Grande Ideia"),t("p",null,[t("strong",null,"Seu cérebro é sua ferramenta mais importante na petanca. Alimente-o com combustível estável, não com energia instável."),n(" Concentre-se em proteínas, gorduras saudáveis e em manter-se hidratado. Evite picos de açúcar.")])],-1)),(i(),s(c,null,{default:l(()=>[d(b,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BA%C3%A7%C3%BAcar%2FCarboidratos%20Simples%5D%20--%3E%20B%5BPico%20de%20a%C3%A7%C3%BAcar%20no%20sangue%5D%0A%20%20%20%20B%20--%3E%20C%5BLibera%C3%A7%C3%A3o%20de%20insulina%5D%0A%20%20%20%20C%20--%3E%20D%5BQueda%20de%20a%C3%A7%C3%BAcar%20no%20sangue%5D%0A%20%20%20%20D%20--%3E%20E%5BResposta%20da%20Adrenalina%5D%0A%20%20%20%20E%20--%3E%20F%5BTremores%20e%20Ansiedade%5D%0A%0A%20%20%20%20G%5BProte%C3%ADnas%20e%20gorduras%20saud%C3%A1veis%5D%20--%3E%20H%5BN%C3%ADveis%20est%C3%A1veis%20de%20a%C3%A7%C3%BAcar%20no%20sangue%5D%0A%20%20%20%20H%20--%3E%20I%5BEnergia%20constante%5D%0A%20%20%20%20I%20--%3E%20J%5BFoco%20n%C3%ADtido%5D%0A%20%20%20%20J%20--%3E%20K%5BM%C3%A3os%20firmes%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20G%20fill%3A%23e8f5e9%0A%20%20%20%20style%20K%20fill%3A%23e8f5e9%0A"})]),fallback:l(()=>[...u[0]||(u[0]=[n(" Loading... ",-1)])]),_:1})),u[5]||(u[5]=r('<h2 id="o-desafio-do-atleta-de-precisao" tabindex="-1">O Desafio do Atleta de Precisão <a class="header-anchor" href="#o-desafio-do-atleta-de-precisao" aria-label="Permalink to &quot;O Desafio do Atleta de Precisão&quot;">​</a></h2><p>Ao contrário de esportes de alta intensidade, a petanca não exige grandes reservas de glicogênio nem reposição rápida de energia. O que ela exige é:</p><ul><li><strong>Níveis estáveis de açúcar no sangue</strong> - sem picos ou quedas bruscas</li><li><strong>Clareza mental consistente</strong> - foco que dura o dia todo</li><li><strong>Mãos firmes</strong> - sem tremores ou abalos</li><li><strong>Nervos calmos</strong> - baixa ansiedade e resposta ao estresse</li></ul><p>Sua estratégia nutricional deve otimizar esses fatores, e não a produção bruta de energia.</p><h2 id="o-problema-com-o-acucar-e-os-carboidratos-simples" tabindex="-1">O problema com o açúcar e os carboidratos simples <a class="header-anchor" href="#o-problema-com-o-acucar-e-os-carboidratos-simples" aria-label="Permalink to &quot;O problema com o açúcar e os carboidratos simples&quot;">​</a></h2><p>Muitos atletas optam por dietas ricas em carboidratos. Para jogadores de petanca, isso pode, na verdade, prejudicar o desempenho.</p><h3 id="a-montanha-russa-do-acucar-no-sangue" tabindex="-1">A Montanha-Russa do Açúcar no Sangue <a class="header-anchor" href="#a-montanha-russa-do-acucar-no-sangue" aria-label="Permalink to &quot;A Montanha-Russa do Açúcar no Sangue&quot;">​</a></h3><p>Quando você consome açúcar ou carboidratos simples:</p><ol><li>O nível de açúcar no sangue aumenta rapidamente.</li><li>A insulina é liberada para diminuir a concentração de insulina.</li><li>Queda brusca de açúcar no sangue (hipoglicemia)</li><li>Seu corpo libera adrenalina para compensar.</li><li>Você apresenta tremores, ansiedade e dificuldade de concentração.</li></ol><p><strong>Isso é o oposto do que você precisa para obter precisão.</strong></p><h3 id="sintomas-de-instabilidade-do-acucar-no-sangue" tabindex="-1">Sintomas de instabilidade do açúcar no sangue <a class="header-anchor" href="#sintomas-de-instabilidade-do-acucar-no-sangue" aria-label="Permalink to &quot;Sintomas de instabilidade do açúcar no sangue&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sintoma</th><th>Impacto no desempenho</th></tr></thead><tbody><tr><td>mãos trêmulas</td><td>Lançamento inconsistente</td></tr><tr><td>Dificuldade de concentração</td><td>Tomada de decisões ruins</td></tr><tr><td>Irritabilidade</td><td>Conflito de equipe, falta de compostura</td></tr><tr><td>Fadiga após as refeições</td><td>moleza da tarde</td></tr><tr><td>Ansiedade</td><td>Sensibilidade à pressão</td></tr><tr><td>Névoa mental</td><td>Pensamento tático lento</td></tr></tbody></table><h2 id="uma-abordagem-melhor-energia-estavel" tabindex="-1">Uma abordagem melhor: energia estável <a class="header-anchor" href="#uma-abordagem-melhor-energia-estavel" aria-label="Permalink to &quot;Uma abordagem melhor: energia estável&quot;">​</a></h2><p>O objetivo é fornecer ao seu cérebro combustível constante, sem oscilações bruscas.</p><h3 id="principios-chave" tabindex="-1">Princípios-chave <a class="header-anchor" href="#principios-chave" aria-label="Permalink to &quot;Princípios-chave&quot;">​</a></h3><ol><li><strong>Priorize proteínas e gorduras saudáveis</strong> - Elas fornecem energia lenta e constante.</li><li><strong>Prefira carboidratos complexos aos simples</strong> - Se for consumir carboidratos, escolha aqueles que são digeridos lentamente.</li><li><strong>Evite picos de açúcar</strong> - Especialmente antes e durante a competição.</li><li><strong>Mantenha-se hidratado</strong> - A desidratação afeta significativamente a concentração.</li><li><strong>Alimente-se regularmente</strong> - Não deixe a fome chegar a um ponto em que você não consegue se controlar.</li></ol><h3 id="alimentos-que-ajudam" tabindex="-1">Alimentos que ajudam <a class="header-anchor" href="#alimentos-que-ajudam" aria-label="Permalink to &quot;Alimentos que ajudam&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo de alimento</th><th>Exemplos</th><th>Por que funciona</th></tr></thead><tbody><tr><td>Proteína</td><td>Ovos, nozes, queijo, carne</td><td>Digestão lenta, energia estável</td></tr><tr><td>Gorduras saudáveis</td><td>Abacate, azeite, nozes</td><td>Combustível de longa duração</td></tr><tr><td>Carboidratos complexos</td><td>Vegetais, leguminosas</td><td>A fibra retarda a absorção.</td></tr><tr><td>Frutas com baixo teor de açúcar</td><td>Frutas vermelhas, maçãs</td><td>Nutrientes sem picos</td></tr></tbody></table><h3 id="alimentos-a-limitar" tabindex="-1">Alimentos a limitar <a class="header-anchor" href="#alimentos-a-limitar" aria-label="Permalink to &quot;Alimentos a limitar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo de alimento</th><th>Exemplos</th><th>Por que isso é problemático</th></tr></thead><tbody><tr><td>Açúcar</td><td>Doces, refrigerantes, bolos</td><td>Pico e queda rápidos</td></tr><tr><td>Pão branco/massa</td><td>Sanduíches, pratos de massa</td><td>Conversão rápida em açúcar</td></tr><tr><td>Suco de frutas</td><td>Suco de laranja, smoothies</td><td>Açúcar concentrado</td></tr><tr><td>Bebidas energéticas</td><td>A maioria das marcas comerciais</td><td>Açúcar + cafeína</td></tr></tbody></table><h2 id="nutricao-para-o-dia-da-competicao" tabindex="-1">Nutrição para o dia da competição <a class="header-anchor" href="#nutricao-para-o-dia-da-competicao" aria-label="Permalink to &quot;Nutrição para o dia da competição&quot;">​</a></h2><h3 id="antes-da-competicao" tabindex="-1">Antes da competição <a class="header-anchor" href="#antes-da-competicao" aria-label="Permalink to &quot;Antes da competição&quot;">​</a></h3><p><strong>2 a 3 horas antes:</strong></p><ul><li>Refeição balanceada com proteínas, gorduras e vegetais.</li><li>Evite carboidratos pesados que possam causar sonolência.</li><li>Exemplo: Ovos com legumes ou salada com frango</li></ul><p><strong>1 hora antes:</strong></p><ul><li>Lanche leve, se necessário</li><li>Nozes, queijo ou uma pequena porção de proteína.</li><li>Evite tudo que seja açucarado</li></ul><h3 id="durante-a-competicao" tabindex="-1">Durante a competição <a class="header-anchor" href="#durante-a-competicao" aria-label="Permalink to &quot;Durante a competição&quot;">​</a></h3><p><strong>Entre os jogos:</strong></p><ul><li>Água (a mais importante)</li><li>Pequenos lanches proteicos (nozes, queijo, carne)</li><li>Evite lanches e bebidas açucaradas.</li></ul><p><strong>Sinais de que você precisa comer:</strong></p><ul><li>Dificuldade de concentração</li><li>Irritabilidade</li><li>Sentindo-me trêmula</li><li>Dor de cabeça</li></ul><h3 id="apos-a-competicao" tabindex="-1">Após a competição <a class="header-anchor" href="#apos-a-competicao" aria-label="Permalink to &quot;Após a competição&quot;">​</a></h3><ul><li>Reponha as energias com uma refeição equilibrada.</li><li>Reidrate-se completamente.</li><li>Não se &quot;recompense&quot; com açúcar - isso afetará sua recuperação.</li></ul><h2 id="hidratacao" tabindex="-1">Hidratação <a class="header-anchor" href="#hidratacao" aria-label="Permalink to &quot;Hidratação&quot;">​</a></h2><p>A desidratação afeta a função cognitiva antes mesmo de você sentir sede.</p><h3 id="diretrizes" tabindex="-1">Diretrizes <a class="header-anchor" href="#diretrizes" aria-label="Permalink to &quot;Diretrizes&quot;">​</a></h3><ul><li><strong>Comece o dia hidratado</strong> - Beba água ao longo do dia antes da competição.</li><li><strong>Durante o jogo</strong> - Beba água regularmente, não espere até sentir sede.</li><li><strong>Evite o excesso de cafeína</strong> - Ela é diurética.</li><li><strong>Fique atento aos sinais:</strong> Dor de cabeça, urina escura, fadiga.</li></ul><h3 id="quanto" tabindex="-1">Quanto? <a class="header-anchor" href="#quanto" aria-label="Permalink to &quot;Quanto?&quot;">​</a></h3><p>Uma regra geral: o ideal é que a urina fique amarelo-clara. Se estiver escura, você precisa beber mais água.</p><h2 id="a-opcao-com-baixo-teor-de-carboidratos" tabindex="-1">A opção com baixo teor de carboidratos <a class="header-anchor" href="#a-opcao-com-baixo-teor-de-carboidratos" aria-label="Permalink to &quot;A opção com baixo teor de carboidratos&quot;">​</a></h2><p>Alguns atletas de precisão adotam dietas com baixo teor de carboidratos ou cetogênicas. A teoria:</p><p><strong>Benefícios potenciais:</strong></p><ul><li>Níveis de açúcar no sangue muito estáveis (sem possibilidade de picos).</li><li>Clareza mental consistente</li><li>Redução da ansiedade e dos tremores</li><li>Sem quedas bruscas de energia à tarde.</li></ul><p><strong>Considerações:</strong></p><ul><li>Requer período de adaptação (1-2 semanas)</li><li>Não é adequado para todos.</li><li>Requer planejamento e comprometimento.</li><li>Consulte primeiro um profissional de saúde</li></ul><p>Essa é uma estratégia avançada – não necessária para todos, mas que vale a pena considerar se a estabilidade do açúcar no sangue for uma questão importante para você.</p><h2 id="alimentacao-como-pratica-treinando-seu-corpo" tabindex="-1">Alimentação como prática: treinando seu corpo <a class="header-anchor" href="#alimentacao-como-pratica-treinando-seu-corpo" aria-label="Permalink to &quot;Alimentação como prática: treinando seu corpo&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Conceito Crítico</p><p><strong>A alimentação não é apenas combustível – é algo com que você treina.</strong> Assim como você treina seu arremesso, você precisa treinar sua nutrição para que seu corpo se acostume com a alimentação do dia da competição.</p></div><h3 id="por-que-as-praticas-alimentares-sao-importantes" tabindex="-1">Por que as práticas alimentares são importantes <a class="header-anchor" href="#por-que-as-praticas-alimentares-sao-importantes" aria-label="Permalink to &quot;Por que as práticas alimentares são importantes&quot;">​</a></h3><p>Seu sistema digestivo pode ser treinado. O que você come regularmente se torna aquilo que seu corpo espera e processa melhor. Se você consumir apenas proteínas e vegetais nos dias de competição, seu corpo não estará adaptado a isso.</p><p><strong>O problema:</strong></p><ul><li>Comer alimentos desconhecidos no dia da competição pode causar desconforto digestivo.</li><li>Seu corpo precisa de tempo para se adaptar a novos padrões alimentares.</li><li>Estresse + comida desconhecida = potenciais problemas estomacais</li><li>A ansiedade de desempenho já é ruim o suficiente sem adicionar a ansiedade digestiva.</li></ul><p><strong>A solução:</strong></p><ul><li>Pratique a nutrição para competição durante o treino.</li><li>Incorpore os alimentos que você consome no dia da competição à sua rotina alimentar regular.</li><li>Treine seu corpo para se acostumar com alimentos de energia estável.</li></ul><h3 id="o-processo-de-adaptacao" tabindex="-1">O Processo de Adaptação <a class="header-anchor" href="#o-processo-de-adaptacao" aria-label="Permalink to &quot;O Processo de Adaptação&quot;">​</a></h3>',55)),(i(),s(c,null,{default:l(()=>[d(b,{id:"mermaid-586",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BDieta%20atual%5D%20--%3E%20B%5BMudan%C3%A7as%20graduais%5D%0A%20%20%20%20B%20--%3E%20C%5BAdapta%C3%A7%C3%A3o%20Corporal%20%3Cbr%2F%3E%202%20a%204%20semanas%5D%0A%20%20%20%20C%20--%3E%20D%5BNovo%20Normal%5D%0A%20%20%20%20D%20--%3E%20E%5BPronto%20para%20a%20competi%C3%A7%C3%A3o%5D%0A%0A%20%20%20%20F%5BMudan%C3%A7a%20repentina%20%3Cbr%2F%3E%20Dia%20da%20Competi%C3%A7%C3%A3o%5D%20--%3E%20G%5BDesconforto%20digestivo%5D%0A%20%20%20%20G%20--%3E%20H%5BDesempenho%20ruim%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff3e0%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20H%20fill%3A%23ffebee%0A"})]),fallback:l(()=>[...u[1]||(u[1]=[n(" Loading... ",-1)])]),_:1})),u[6]||(u[6]=r('<p>Ao mudar sua dieta:</p><ol><li><strong>Semanas 1-2:</strong> Seu corpo se adapta aos novos alimentos e você pode sentir algumas diferenças.</li><li><strong>Semanas 3-4:</strong> Ocorre a adaptação, os novos alimentos passam a ser considerados normais.</li><li><strong>Semana 5+:</strong> Seu corpo está confortável e funcionando de forma eficiente com esses alimentos.</li></ol><p><strong>É por isso que você não pode simplesmente &quot;se alimentar de forma saudável&quot; no dia da competição e esperar resultados ótimos.</strong></p><h3 id="como-praticar-sua-nutricao" tabindex="-1">Como praticar sua nutrição <a class="header-anchor" href="#como-praticar-sua-nutricao" aria-label="Permalink to &quot;Como praticar sua nutrição&quot;">​</a></h3><h4 id="_1-comece-durante-o-treinamento" tabindex="-1">1. Comece durante o treinamento <a class="header-anchor" href="#_1-comece-durante-o-treinamento" aria-label="Permalink to &quot;1. Comece durante o treinamento&quot;">​</a></h4><p><strong>Pratique sua alimentação do dia da competição durante os treinos:</strong></p><ul><li>Coma a mesma refeição pré-treino que você comeria antes de uma competição.</li><li>Leve os mesmos lanches que você levaria para um torneio.</li><li>Observe como seu corpo reage.</li><li>Ajuste com base no que funciona.</li></ul><p><strong>Exemplo de dia de treinamento:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2-3 hours before: Eggs with vegetables (same as competition)</span></span>\n<span class="line"><span>During training: Water + nuts (same as competition)</span></span>\n<span class="line"><span>After training: Balanced meal with protein</span></span></code></pre></div><h4 id="_2-faca-disso-o-seu-normal" tabindex="-1">2. Faça disso o seu normal <a class="header-anchor" href="#_2-faca-disso-o-seu-normal" aria-label="Permalink to &quot;2. Faça disso o seu normal&quot;">​</a></h4><p><strong>Não tenha uma &quot;dieta de competição&quot; e uma &quot;dieta normal&quot;</strong> - isso cria dois problemas:</p><ul><li>Seu corpo nunca se adapta completamente a nenhum dos dois.</li><li>A comida da competição parece estranha e estressante.</li></ul><p><strong>Em vez de:</strong></p><ul><li>Faça dos alimentos com alto teor energético a sua norma diária.</li><li>Seu corpo se torna eficiente no uso de proteínas e gorduras.</li><li>O dia da competição parece normal, não diferente.</li><li>Sem surpresas digestivas</li></ul><h4 id="_3-testar-e-refinar" tabindex="-1">3. Testar e refinar <a class="header-anchor" href="#_3-testar-e-refinar" aria-label="Permalink to &quot;3. Testar e refinar&quot;">​</a></h4><p><strong>Use o treinamento para experimentar:</strong></p><table tabindex="0"><thead><tr><th>Teste</th><th>O que observar</th><th>Ajustar</th></tr></thead><tbody><tr><td>Horário da refeição pré-treino</td><td>Níveis de energia, foco</td><td>Encontre a sua janela ideal.</td></tr><tr><td>Diferentes fontes de proteína</td><td>Digestão, conforto</td><td>Identifique o que funciona melhor</td></tr><tr><td>Tipos de lanches</td><td>Energia sustentada</td><td>Encontre seus lanches favoritos</td></tr><tr><td>Quantidades de hidratação</td><td>Concentração, pausas para ir ao banheiro</td><td>ingestão equilibrada</td></tr></tbody></table><p><strong>Mantenha um registro simples:</strong></p><ul><li>O que você comeu e quando?</li><li>Como você se sentiu durante o treinamento?</li><li>Níveis de energia e concentração</li><li>Quaisquer problemas digestivos</li></ul><h4 id="_4-desenvolva-conforto-e-confianca" tabindex="-1">4. Desenvolva conforto e confiança <a class="header-anchor" href="#_4-desenvolva-conforto-e-confianca" aria-label="Permalink to &quot;4. Desenvolva conforto e confiança&quot;">​</a></h4><p><strong>O benefício psicológico:</strong></p><p>Quando você já praticou sua alimentação centenas de vezes durante o treinamento:</p><ul><li>Você sabe exatamente como seu corpo reagirá.</li><li>Sem ansiedade em relação às opções alimentares.</li><li>Uma preocupação a menos no dia da competição.</li><li>Confiança na sua preparação</li></ul><p><strong>Este é o mesmo princípio de praticar o arremesso</strong> - a repetição gera conforto e confiabilidade.</p><h3 id="desafios-comuns-de-adaptacao" tabindex="-1">Desafios comuns de adaptação <a class="header-anchor" href="#desafios-comuns-de-adaptacao" aria-label="Permalink to &quot;Desafios comuns de adaptação&quot;">​</a></h3><details class="details custom-block"><summary>Transição de uma dieta rica em carboidratos para uma dieta com energia estável.</summary><p><strong>Desafio:</strong> Você está acostumado(a) a pão, macarrão e doces.</p><p><strong>Período de adaptação:</strong> 2 a 4 semanas</p><p><strong>O que esperar:</strong></p><ul><li>Semana 1: Pode haver sensações diferentes, desejos por comidas antigas.</li><li>Semana 2: Os níveis de energia se estabilizam e os desejos diminuem.</li><li>Semanas 3-4: Novo normal, corpo eficiente com gorduras/proteínas</li></ul><p><strong>Como praticar:</strong></p><ul><li>Comece com uma refeição de cada vez.</li><li>Substitua primeiro os carboidratos simples por carboidratos complexos.</li><li>Aumente gradualmente a ingestão de proteínas e gorduras saudáveis.</li><li>Pratique primeiro durante treinos de baixo risco.</li></ul></details><details class="details custom-block"><summary>Encontrando alimentos que funcionam para você</summary><p><strong>Desafio:</strong> Nem todos digerem bem os mesmos alimentos.</p><p><strong>O que testar:</strong></p><ul><li>Diferentes fontes de proteína (ovos vs. carne vs. nozes)</li><li>Horário das refeições (2 horas ou 3 horas antes)</li><li>Tamanho das porções (muita = sensação de lentidão, pouca = fome)</li><li>Alimentos específicos que causam desconforto</li></ul><p><strong>Abordagem prática:</strong></p><ul><li>Tente uma variável de cada vez.</li><li>Dê a cada teste de 2 a 3 sessões de treinamento.</li><li>Anote o que te faz sentir melhor</li><li>Monte seu &quot;cardápio de competição&quot; personalizado</li></ul></details><details class="details custom-block"><summary>Lidando com ambientes alimentares em torneios</summary><p><strong>Desafio:</strong> Os torneios geralmente têm opções limitadas de alimentação.</p><p><strong>Solução prática:</strong></p><ul><li>Leve sempre seus próprios lanches (pratique isso).</li><li>Visite os locais com antecedência, sempre que possível.</li><li>Tenha opções de backup que você sabe que funcionam.</li><li>Pratique comer em diferentes ambientes.</li></ul><p><strong>Preparação mental:</strong></p><ul><li>Não confie na comida do local.</li><li>Trate os alimentos como parte do seu equipamento.</li><li>Embale como você embala suas bolas de bocha.</li></ul></details><h3 id="plano-de-pratica-nutricional-de-30-dias" tabindex="-1">Plano de Prática Nutricional de 30 Dias <a class="header-anchor" href="#plano-de-pratica-nutricional-de-30-dias" aria-label="Permalink to &quot;Plano de Prática Nutricional de 30 Dias&quot;">​</a></h3><p><strong>Objetivo:</strong> Fazer da alimentação com energia estável o seu normal, algo que lhe seja confortável.</p><p><strong>Semanas 1-2: Fundamentos</strong></p><ul><li>Substitua uma refeição por dia por uma alimentação no estilo de competição.</li><li>Pratique a nutrição pré-treino.</li><li>Comece a levar lanches para o treino.</li><li>Observe como seu corpo reage.</li></ul><p><strong>Semanas 3-4: Expansão</strong></p><ul><li>Faça duas refeições por dia com foco em energia estável.</li><li>Pratique a alimentação completa do dia da competição nos dias de treino.</li><li>Aprimore suas opções de lanches</li><li>Crie sua lista de alimentos favoritos</li></ul><p><strong>Semana 5+: Domínio</strong></p><ul><li>Alimentação com níveis energéticos estáveis será o seu novo normal.</li><li>O corpo está totalmente adaptado.</li><li>O dia da competição parece rotineiro.</li><li>Confiança na sua nutrição</li></ul><h3 id="seu-kit-de-alimentos-para-competicao" tabindex="-1">Seu kit de alimentos para competição <a class="header-anchor" href="#seu-kit-de-alimentos-para-competicao" aria-label="Permalink to &quot;Seu kit de alimentos para competição&quot;">​</a></h3><p><strong>Pratique levar este item para cada sessão de treinamento:</strong></p><p><strong>Pré-competição (2 a 3 horas antes):</strong></p><ul><li>[ ] Fonte de proteína (ovos, carne ou nozes)</li><li>[ ] Legumes ou salada</li><li>[ ] Gorduras saudáveis (abacate, azeite, queijo)</li></ul><p><strong>Durante a competição:</strong></p><ul><li>[ ] Garrafa de água (reutilizável)</li><li>[ ] Mix de nozes (porções pequenas)</li><li>[ ] Ovos cozidos (se você conseguir mantê-los frescos)</li><li>[ ] Cubos de queijo ou queijo em tiras</li><li>[ ] carne seca ou carne desidratada</li><li>[ ] Lanches de reserva</li></ul><p><strong>Quanto mais você praticar com este kit, mais automático ele se tornará.</strong></p><h2 id="dicas-praticas" tabindex="-1">Dicas práticas <a class="header-anchor" href="#dicas-praticas" aria-label="Permalink to &quot;Dicas práticas&quot;">​</a></h2><h3 id="lanches-faceis-para-competicao" tabindex="-1">Lanches fáceis para competição <a class="header-anchor" href="#lanches-faceis-para-competicao" aria-label="Permalink to &quot;Lanches fáceis para competição&quot;">​</a></h3><ul><li>Mix de frutos secos (sem sal)</li><li>Ovos cozidos</li><li>Cubos de queijo</li><li>Carne seca de boi ou de peru</li><li>Legumes com húmus</li><li>Azeitonas</li></ul><h3 id="o-que-evitar" tabindex="-1">O que evitar <a class="header-anchor" href="#o-que-evitar" aria-label="Permalink to &quot;O que evitar&quot;">​</a></h3><ul><li>salgadinhos de máquina de venda automática</li><li>bebidas esportivas açucaradas</li><li>Pastéis e produtos de panificação</li><li>Barras de chocolate e doces</li><li>A maioria das barras &quot;energéticas&quot; (verifique o teor de açúcar)</li></ul><h2 id="ponto-chave" tabindex="-1">Ponto-chave <a class="header-anchor" href="#ponto-chave" aria-label="Permalink to &quot;Ponto-chave&quot;">​</a></h2><blockquote><p>Seu cérebro é sua ferramenta mais importante na petanca. Alimente-o com combustível estável, não com energia instável. E pratique sua nutrição assim como pratica seu arremesso — a repetição gera conforto e confiabilidade.</p></blockquote><p>Priorize proteínas, gorduras saudáveis e mantenha-se hidratado. Evite picos de açúcar. <strong>O mais importante: adote a nutrição do dia da competição como sua nutrição diária.</strong> Seu corpo precisa de prática para atingir o máximo desempenho.</p><p><strong>Lembre-se:</strong> Você não apareceria em um torneio com uma técnica de arremesso que nunca praticou. Da mesma forma, não apareça com uma estratégia de nutrição que nunca praticou.</p>',52))])}]]);export{u as __pageData,m as default};
